//! Parity of `LCEMGP` (the Unity project's contextual models) and of
//! `Interval` constraints with BoTorch (fixtures in
//! `tests/fixtures/unity_lcemgp/*.json`, generated by
//! `scripts/generate_fixtures.py --phase unity-lcemgp`).
//!
//! Every model case is one of the Unity project's LCE-M GPs on BoTorch
//! (`learned` embeddings, `provided` embeddings with a context-specific
//! weight, and `stock`, learned plus fixed embeddings) with K = 2, 3, 5
//! contexts, some without data, m = 1, 3 fixed embedding dimensions and
//! d = 1, ..., 4 inputs:
//!
//! * the optimizer's parameter names, sizes and bounds and the default raw
//!   parameters (exact);
//! * MLL values (1e-9, relative) and gradients (1e-8, relative to the
//!   largest component) at the default and at random raw parameters, and
//!   the in-place renormalization of the embedding weights by a forward
//!   pass (exact);
//! * the constant means of unobserved contexts after `eval()` (exact up to
//!   rounding) and posteriors over the output task (with and without
//!   observation noise), over all tasks and at inputs with a task column,
//!   and the gradient of a weighted sum of the posterior mean and covariance
//!   with respect to the inputs (1e-9);
//! * `fit_gpytorch_mll` from the default parameters, compared with BoTorch's
//!   outcomes: its own fit, the fit with the optimizer's variables reversed
//!   and the fits of 16 twins whose training inputs are perturbed at 1e-14 ..
//!   1e-11 (long L-BFGS-B runs on these likelihoods end in other optima under
//!   rounding-level changes, in either library). botorch_rs fits the same
//!   twins; its best final loss must reach BoTorch's best, and its own fit
//!   must not end above BoTorch's worst outcome, both within max(1e-6, 10 ×
//!   the spread of BoTorch's outcomes at its best optimum);
//! * qLogNEI and qLogNEHVI (on a list with a second model) with BoTorch's
//!   recorded base samples: per candidate set, the nearest of BoTorch's
//!   outcomes on the model and its 16 twins (on nearly singular posteriors
//!   BoTorch's result jumps between regimes, depending on whether a Cholesky
//!   factorization needs jitter); values 1e-9 (log values absolute below 1)
//!   and gradients 1e-8, or 10 × BoTorch's median change on the twins,
//!   whichever is larger.
//!
//! `interval.json`: `Interval` values, inverses, derivatives, raw initial
//! values and optimizer bounds (1e-15), and `SingleTaskGP`s with `Interval`
//! constraints on the lengthscales, the outputscale and the noise (MLL
//! values and gradients, fits with the same tolerance). Run with `--nocapture` to print the error
//! tables.

mod common;

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::Arc;

use botorch_core::acquisition::multi_objective::{
    QLogNoisyExpectedHypervolumeImprovement, QLogNoisyExpectedHypervolumeImprovementOptions,
};
use botorch_core::acquisition::{
    AcquisitionFunction, QLogNoisyExpectedImprovement, QLogNoisyExpectedImprovementOptions,
};
use botorch_core::constraints::{Interval, ParameterTransform};
use botorch_core::kernels::{KernelKind, KernelSpec, ScaleKernelSpec};
use botorch_core::models::{LCEMGPOptions, LCEMGP};
use botorch_core::{
    fit_gpytorch_mll, get_gaussian_likelihood_with_lognormal_prior, FitOptions,
    GaussianLikelihoodSpec, Matrix, Model, ModelList, SingleTaskGP, SingleTaskGPOptions,
    SobolQMCNormalSampler, Vector,
};
use common::{fixture_dir, matrix, rel_err, Report};
use serde::Deserialize;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const FIT_TOL: f64 = 1e-6;
/// BoTorch's fit outcomes within this distance of its best final loss count
/// as the same optimum; their spread sets the fit tolerance.
const FIT_CLUSTER: f64 = 1e-4;
/// Two float32 units in the last place (relative).
const F32_ULP: f64 = 2.4e-7;
/// The seed of the samplers (every dimension has a recorded draw).
const UNRECORDED_SEED: u64 = 4242;

/// A number of a fixture; non-finite numbers are the strings "inf", "-inf"
/// and "nan".
#[derive(Debug, Clone, Copy)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Raw {
            F(f64),
            S(String),
        }
        Ok(F(match Raw::deserialize(d)? {
            Raw::F(v) => v,
            Raw::S(s) => match s.as_str() {
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                "nan" => f64::NAN,
                other => return Err(serde::de::Error::custom(format!("not a number: {other}"))),
            },
        }))
    }
}

fn vals(v: &[F]) -> Vec<f64> {
    v.iter().map(|f| f.0).collect()
}

fn rows(v: &[Vec<F>]) -> Vec<Vec<f64>> {
    v.iter().map(|r| vals(r)).collect()
}

