#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    variant: String,
    num_contexts: usize,
    current: i64,
    unobserved: Vec<usize>,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    embeddings: Option<Vec<Vec<f64>>>,
    embedding_init: Option<Vec<Vec<f64>>>,
    param_names: Vec<(String, usize)>,
    bounds: Vec<Vec<F>>,
    default_raw_params: Vec<f64>,
    default_mll: Mll,
    fit: Fit,
    raw_params: Vec<f64>,
    mll: Mll,
    raw_params_after_forward: Vec<f64>,
    eval_constants: Vec<f64>,
    test_x: Vec<Vec<f64>>,
    posterior: Joint,
    posterior_all_tasks: AllTasks,
    posterior_task_inputs: TaskInputs,
    vjp: Vjp,
    qlognei: Vec<McEval>,
    nehvi: Nehvi,
}

fn load_cases() -> Vec<Case> {
    let dir = fixture_dir().join("unity_lcemgp");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.extension().is_some_and(|e| e == "json")
                && p.file_name().is_some_and(|n| n != "interval.json")
        })
        .collect();
    paths.sort();
    assert!(
        !paths.is_empty(),
        "run generate_fixtures.py --phase unity-lcemgp"
    );
    paths
        .iter()
        .map(|p| serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap())
        .collect()
}

/// The model of a case (as the Unity project builds it) on targets `y`.
fn build(c: &Case, y: &[Vec<f64>], embedding_init: Option<&Vec<Vec<f64>>>) -> LCEMGP {
    build_on(c, &c.train_x, y, embedding_init)
}

/// The model of `c` on the training inputs `x` (with the task column).
fn build_on(
    c: &Case,
    x: &[Vec<f64>],
    y: &[Vec<f64>],
    embedding_init: Option<&Vec<Vec<f64>>>,
) -> LCEMGP {
    let k = c.num_contexts;
    let mut options = LCEMGPOptions {
        output_tasks: Some(vec![c.current]),
        all_tasks: Some((0..k as i64).collect()),
        context_cat_feature: Some(Matrix::from_fn(k, 1, |i, _| i as f64)),
        ..Default::default()
    };
    match c.variant.as_str() {
        "learned" => {
            options.embs_dim_list = Some(vec![1]);
        }
        "provided" => {
            options.context_emb_feature = Some(matrix(c.embeddings.as_ref().unwrap()));
            options.provided_embedding = true;
        }
        "stock" => {
            options.context_emb_feature = Some(matrix(c.embeddings.as_ref().unwrap()));
            options.embs_dim_list = Some(vec![1]);
        }
        other => panic!("unknown variant {other}"),
    }
    if let Some(w) = embedding_init {
        options.embedding_weights = Some(vec![matrix(w)]);
    }
    LCEMGP::new(matrix(x), matrix(y), -1, options).unwrap()
}

fn log_err(a: &[f64], e: &[f64]) -> f64 {
    a.iter()
        .zip(e)
        .map(|(a, e)| {
            if a == e {
                0.0
            } else {
                (a - e).abs() / e.abs().max(1.0)
            }
        })
        .fold(0.0, f64::max)
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    a.iter()
        .zip(e)
        .map(|(a, e)| (a - e).abs() / scale.max(1e-300))
        .fold(0.0, f64::max)
}

fn sampler(draws: &BTreeMap<String, Vec<Vec<f64>>>) -> Arc<SobolQMCNormalSampler> {
    let n = draws.values().next().map_or(1, |z| z.len());
    let s = SobolQMCNormalSampler::new(n, Some(UNRECORDED_SEED)).unwrap();
    for z in draws.values() {
        s.set_base_samples(matrix(z)).unwrap();
    }
    Arc::new(s)
}

/// The median of `xs` (the mean of the two middle values for an even count).
fn median(mut xs: Vec<f64>) -> f64 {
    xs.sort_by(f64::total_cmp);
    let n = xs.len();
    if n % 2 == 1 {
        xs[n / 2]
    } else {
        0.5 * (xs[n / 2 - 1] + xs[n / 2])
    }
}

/// Compares the MC evaluations (values in log space) of `acqf`, per
/// candidate set, with the nearest of BoTorch's outcomes (on the model and
/// its twins), within 10 × BoTorch's median change on the twins.
fn check_mc(
    report: &mut Report,
    name: &str,
    what: &str,
    acqf: &dyn AcquisitionFunction,
    e: &McEval,
) {
    let mut values = Vec::new();
    let mut grads = Vec::new();
    for x in &e.x {
        let (v, g) = acqf.forward_with_grad(&matrix(x)).unwrap();
        values.push(v);
        grads.push(common::matrix_rows(&g));
    }
    let flat =
        |g: &[Vec<Vec<f64>>]| -> Vec<Vec<f64>> { g.iter().map(|set| set.concat()).collect() };
    let outcomes: Vec<(Vec<f64>, Vec<Vec<f64>>)> =
        std::iter::once((vals(&e.values), flat(&e.grads)))
            .chain(
                e.twin_values
                    .iter()
                    .zip(&e.twin_grads)
                    .map(|(v, g)| (vals(v), flat(g))),
            )
            .collect();
    let (base_v, base_g) = &outcomes[0];
    let floor_v = median(
        outcomes[1..]
            .iter()
            .map(|(v, _)| log_err(v, base_v))
            .collect(),
    );
    let floor_g = median(
        outcomes[1..]
            .iter()
            .map(|(_, g)| grad_err(&g.concat(), &base_g.concat()))
            .collect(),
    );
    let tol_v = VALUE_TOL.max(10.0 * floor_v);
    let tol_g = GRAD_TOL.max(10.0 * floor_g);
    // Per candidate set, the nearest outcome (errors relative to the
    // tolerances; at most 1 passes) and its unscaled errors.
    let mut worst = (0.0f64, 0.0f64, 0.0f64);
    for (i, (v, g)) in values.iter().zip(&grads).enumerate() {
        let nearest = outcomes
            .iter()
            .map(|(ov, og)| {
                let ev = log_err(std::slice::from_ref(v), &ov[i..=i]);
                let eg = grad_err(g, &og[i]);
                ((ev / tol_v).max(eg / tol_g), ev, eg)
            })
            .min_by(|a, b| a.0.total_cmp(&b.0))
            .unwrap();
        if nearest.0 > worst.0 {
            worst = nearest;
        }
    }
    let regimes = outcomes[1..]
        .iter()
        .any(|(v, _)| log_err(v, base_v) > 100.0 * tol_v);
    let label = format!("{what} q={}", e.q);
    report.check(
        name,
        &format!("{label} values (unscaled, nearest)"),
        worst.1,
        f64::INFINITY,
    );
    report.check(
        name,
        &format!("{label} gradients (unscaled, nearest)"),
        worst.2,
        f64::INFINITY,
    );
    report.check(
        name,
        &format!("{label} BoTorch outcomes in several regimes"),
        f64::from(u8::from(regimes)),
        f64::INFINITY,
    );
    report.check(
        name,
        &format!("{label} values and gradients (scaled)"),
        worst.0,
        1.0,
    );
}

#[test]
fn lcemgp_matches_botorch() {
    let mut report = Report::default();
    for c in load_cases() {
        let name = c.name.as_str();
        let mut gp = build(&c, &c.train_y, c.embedding_init.as_ref());
        // Structure and initialization.
        let names = gp.parameter_names();
        assert_eq!(names, c.param_names, "{name}: parameter names");
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|b| (b[0].0, b[1].0)).collect();
        assert_eq!(gp.raw_parameter_bounds(), bounds, "{name}: bounds");
        report.check_slices(
            name,
            "default raw parameters",
            gp.raw_parameters().as_slice(),
            &c.default_raw_params,
            0.0,
        );
        let (v, g) = gp.mll_value_and_grad(&c.default_raw_params).unwrap();
        report.check(
            name,
            "default MLL",
            (v - c.default_mll.value).abs() / c.default_mll.value.abs(),
            VALUE_TOL,
        );
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );

        // Fit from the default parameters, renormalized by BoTorch's forward
        // pass of the MLL evaluation.
        let mut fitted = gp.clone();
        fitted.renorm_embeddings();
        report.check_slices(
            name,
            "fit: initial raw parameters",
            fitted.raw_parameters().as_slice(),
            &c.fit.initial_raw_params,
            0.0,
        );
        let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
        // BoTorch's outcomes, and botorch_rs's on the same twins.
        let bt: Vec<f64> = [c.fit.loss, c.fit.reversed_loss]
            .into_iter()
            .chain(c.fit.twin_losses.iter().copied())
            .collect();
        let rs: Vec<f64> = std::iter::once(r.loss)
            .chain(c.fit.twin_train_x.iter().map(|x| {
                let mut twin = build_on(&c, x, &c.train_y, c.embedding_init.as_ref());
                twin.renorm_embeddings();
                fit_gpytorch_mll(&mut twin, FitOptions::default())
                    .unwrap()
                    .loss
            }))
            .collect();
        let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
        let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
        let rs_worst = rs.iter().copied().fold(f64::NEG_INFINITY, f64::max);
        let spread = bt
            .iter()
            .copied()
            .filter(|&l| l <= bt_best + FIT_CLUSTER)
            .fold(bt_best, f64::max)
            - bt_best;
        let tol = FIT_TOL.max(10.0 * spread);
        report.check(
            name,
            "fit: best loss above BoTorch's best (scaled)",
            (rs_best - bt_best).max(0.0) / tol,
            1.0,
        );
        report.check(
            name,
            "fit: loss above BoTorch's worst outcome (scaled)",
            (r.loss - bt_worst).max(0.0) / tol,
            1.0,
        );
        let parameter_difference = fitted
            .raw_parameters()
            .iter()
            .zip(&c.fit.raw_params)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0, f64::max);
        println!(
            "{name:28} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), max \
             parameter difference {parameter_difference:.1e}; outcomes with the 16 twins: BoTorch \
             [{bt_best:+.10}, {bt_worst:+.10}], botorch_rs [{rs_best:+.10}, {rs_worst:+.10}], \
             spread at BoTorch's best {spread:.1e}",
            r.loss, c.fit.loss, r.iterations, c.fit.iterations,
        );

        // Random hyperparameters: MLL, renormalization by a forward pass.
        gp.set_raw_parameters(&c.raw_params).unwrap();
        let (v, g) = gp.mll_value_and_grad(&c.raw_params).unwrap();
        report.check(
            name,
            "MLL",
            (v - c.mll.value).abs() / c.mll.value.abs(),
            VALUE_TOL,
        );
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        gp.renorm_embeddings();
        report.check_slices(
            name,
            "renormalized embedding weights",
            gp.raw_parameters().as_slice(),
            &c.raw_params_after_forward,
            0.0,
        );
        // eval(): the constants of unobserved contexts.
        gp.eval_unobserved_means();
        report.check_slices(
            name,
            "constants after eval()",
            gp.constant().as_slice(),
            &c.eval_constants,
            1e-15,
        );
        assert!(c
            .unobserved
            .iter()
            .all(|&t| !gp.task_layout().is_observed(t)));

        // Posteriors.
        let x = matrix(&c.test_x);
        let p = Model::posterior(&gp, &x, false).unwrap();
        report.check_slices(
            name,
            "posterior mean",
            p.mean.as_slice(),
            &c.posterior.mean,
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "posterior covariance",
            &common::matrix_rows(&p.covariance),
            &common::flatten(&c.posterior.covariance),
            VALUE_TOL,
        );
        let pn = Model::posterior(&gp, &x, true).unwrap();
        report.check_slices(
            name,
            "posterior covariance (noise)",
            &common::matrix_rows(&pn.covariance),
            &common::flatten(&c.posterior.covariance_noisy),
            VALUE_TOL,
        );
        let all = gp.with_output_tasks(&c.posterior_all_tasks.tasks).unwrap();
        let pa = Model::posterior(&all, &x, false).unwrap();
        let q = x.nrows();
        let mean_all: Vec<f64> = (0..q * c.num_contexts)
            .map(|j| c.posterior_all_tasks.mean[j % q][j / q])
            .collect();
        report.check_slices(
            name,
            "posterior mean (all tasks)",
            pa.mean.as_slice(),
            &mean_all,
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "posterior covariance (all tasks)",
            &common::matrix_rows(&pa.covariance),
            &common::flatten(&c.posterior_all_tasks.covariance),
            VALUE_TOL,
        );
        let pt = gp
            .posterior_with_tasks(&matrix(&c.posterior_task_inputs.x), false)
            .unwrap();
        report.check_slices(
            name,
            "posterior mean (task inputs)",
            pt.mean.as_slice(),
            &c.posterior_task_inputs.mean,
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "posterior covariance (task inputs)",
            &common::matrix_rows(&pt.covariance),
            &common::flatten(&c.posterior_task_inputs.covariance),
            VALUE_TOL,
        );
        let vjp = gp
            .joint_posterior_vjp(
                &x,
                0..q,
                &Vector::from_vec(c.vjp.mean_adjoint.clone()),
                &matrix(&c.vjp.covariance_adjoint),
            )
            .unwrap();
        report.check(
            name,
            "posterior VJP",
            grad_err(&common::matrix_rows(&vjp), &common::flatten(&c.vjp.grad)),
            GRAD_TOL,
        );

        // qLogNEI.
        let model: Arc<dyn Model> = Arc::new(gp.clone());
        let xb = gp.train_inputs().columns(0, gp.dim()).into_owned();
        for e in &c.qlognei {
            let acqf = QLogNoisyExpectedImprovement::new(
                Arc::clone(&model),
                &xb,
                QLogNoisyExpectedImprovementOptions {
                    sampler: Some(sampler(&e.draws)),
                    prune_baseline: false,
                    ..Default::default()
                },
            )
            .unwrap();
            check_mc(&mut report, name, "qLogNEI", &acqf, e);
        }
        // qLogNEHVI on a list of two models.
        let mut gp2 = build(&c, &c.nehvi.train_y2, c.embedding_init.as_ref());
        gp2.set_raw_parameters(&c.nehvi.raw_params2).unwrap();
        gp2.eval_unobserved_means();
        let list: Arc<dyn Model> =
            Arc::new(ModelList::new(vec![Arc::clone(&model), Arc::new(gp2)]).unwrap());
        for e in &c.nehvi.evaluations {
            let acqf = QLogNoisyExpectedHypervolumeImprovement::new(
                Arc::clone(&list),
                &c.nehvi.ref_point,
                &xb,
                QLogNoisyExpectedHypervolumeImprovementOptions {
                    sampler: Some(sampler(&e.draws)),
                    prune_baseline: false,
                    ..Default::default()
                },
            )
            .unwrap();
            check_mc(&mut report, name, "qLogNEHVI", &acqf, e);
        }
    }
    report.finish("LCEMGP vs BoTorch (Unity's contextual models)");
}

