#[derive(Debug, Deserialize)]
struct ConstraintCase {
    lower: f64,
    upper: f64,
    transform: Option<String>,
    initial_value: Option<f64>,
    stored_bounds: Vec<f64>,
    raw: Vec<f64>,
    values: Vec<f64>,
    derivatives: Vec<f64>,
    actual: Vec<f64>,
    inverse: Vec<f64>,
    initial_raw: Option<f64>,
    raw_bounds: Vec<F>,
}

#[derive(Debug, Deserialize)]
struct IntervalModel {
    kind: String,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    param_names: Vec<(String, usize)>,
    default_raw_params: Vec<f64>,
    bounds: Vec<Vec<F>>,
    default_mll: Mll,
    fit: IntervalFit,
    raw_params: Vec<f64>,
    mll: Mll,
}

#[derive(Debug, Deserialize)]
struct IntervalFit {
    loss: f64,
    iterations: usize,
    raw_params: Vec<f64>,
    floor: f64,
}

#[derive(Debug, Deserialize)]
struct IntervalFixture {
    constraints: Vec<ConstraintCase>,
    models: Vec<IntervalModel>,
}

fn interval(lower: f64, upper: f64, transform: Option<&str>, initial: Option<f64>) -> Interval {
    let t = transform.map(|t| match t {
        "sigmoid" => ParameterTransform::Sigmoid,
        "softplus" => ParameterTransform::Softplus,
        other => panic!("unknown transform {other}"),
    });
    Interval::new(lower, upper, t, None, initial)
        .unwrap()
        .rounded_to_f32()
}

fn interval_model(m: &IntervalModel) -> SingleTaskGP {
    let d = m.train_x[0].len();
    let mut options = SingleTaskGPOptions::default();
    match m.kind.as_str() {
        "lengthscale_box" => {
            options.covar_module = Some(KernelSpec {
                lengthscale_constraint: interval(0.05, 2.0, None, Some(0.7)).into(),
                ..KernelSpec::new(KernelKind::Rbf, d)
            });
        }
        "lengthscale_sigmoid" => {
            options.covar_module = Some(KernelSpec {
                lengthscale_constraint: interval(0.05, 3.0, Some("sigmoid"), Some(0.9)).into(),
                ..KernelSpec::new(KernelKind::Rbf, d)
            });
        }
        "scale_noise" => {
            let base = KernelSpec {
                lengthscale_constraint: interval(0.02, 4.0, Some("sigmoid"), None).into(),
                ..KernelSpec::new(KernelKind::Rbf, d)
            };
            options.covar_module = Some(base.with_scale_kernel(ScaleKernelSpec {
                outputscale_prior: None,
                outputscale_constraint: interval(0.1, 5.0, None, Some(1.0)).into(),
            }));
            options.likelihood = Some(GaussianLikelihoodSpec {
                noise_prior: None,
                noise_constraint: interval(1e-4, 0.5, None, Some(0.05)).into(),
            });
        }
        other => panic!("unknown kind {other}"),
    }
    let _ = get_gaussian_likelihood_with_lognormal_prior();
    SingleTaskGP::new(matrix(&m.train_x), matrix(&m.train_y), options).unwrap()
}

#[test]
fn interval_matches_gpytorch() {
    let text = std::fs::read_to_string(fixture_dir().join("unity_lcemgp").join("interval.json"))
        .expect("run generate_fixtures.py --phase unity-lcemgp");
    let f: IntervalFixture = serde_json::from_str(&text).unwrap();
    let mut report = Report::default();
    for (i, c) in f.constraints.iter().enumerate() {
        let name = format!("Interval #{i} ({:?})", c.transform);
        let ic = interval(c.lower, c.upper, c.transform.as_deref(), c.initial_value);
        assert_eq!(vec![ic.lower_bound(), ic.upper_bound()], c.stored_bounds);
        let values: Vec<f64> = c.raw.iter().map(|&r| ic.transform(r)).collect();
        report.check_slices(&name, "transform", &values, &c.values, 1e-15);
        let der: Vec<f64> = c.raw.iter().map(|&r| ic.transform_derivative(r)).collect();
        report.check_slices(&name, "derivative", &der, &c.derivatives, 1e-15);
        let inv: Vec<f64> = c.actual.iter().map(|&v| ic.inverse_transform(v)).collect();
        report.check(&name, "inverse transform", rel_err(&inv, &c.inverse), 1e-12);
        // torch's float32 `log` is not correctly rounded, so the raw initial
        // value of an enforced interval can differ by a float32 ulp.
        match (ic.initial_raw_value(), c.initial_raw) {
            (Some(a), Some(e)) => report.check(
                &name,
                "raw initial value",
                (a - e).abs() / e.abs().max(1.0),
                F32_ULP,
            ),
            (a, e) => assert_eq!(a, e, "{name}: initial raw value"),
        }
        let (lo, hi) = ic.raw_bounds();
        assert_eq!(
            (lo, hi),
            (c.raw_bounds[0].0, c.raw_bounds[1].0),
            "{name}: raw bounds"
        );
    }
    for m in &f.models {
        let name = format!("SingleTaskGP {}", m.kind);
        let mut gp = interval_model(m);
        assert_eq!(gp.parameter_names(), m.param_names, "{name}: names");
        let bounds: Vec<(f64, f64)> = m.bounds.iter().map(|b| (b[0].0, b[1].0)).collect();
        assert_eq!(gp.raw_parameter_bounds(), bounds, "{name}: bounds");
        report.check_slices(
            &name,
            "default raw parameters",
            gp.raw_parameters().as_slice(),
            &m.default_raw_params,
            F32_ULP,
        );
        // The fit starts from BoTorch's initial values.
        gp.set_raw_parameters(&m.default_raw_params).unwrap();
        let mll = botorch_core::ExactMarginalLogLikelihood::new(&gp);
        let (v, g) = mll.value_and_grad(&m.default_raw_params).unwrap();
        report.check(
            &name,
            "default MLL",
            (v - m.default_mll.value).abs() / m.default_mll.value.abs(),
            VALUE_TOL,
        );
        report.check(
            &name,
            "default MLL gradient",
            grad_err(g.as_slice(), &m.default_mll.grad),
            GRAD_TOL,
        );
        let (v, g) = mll.value_and_grad(&m.raw_params).unwrap();
        report.check(
            &name,
            "MLL",
            (v - m.mll.value).abs() / m.mll.value.abs(),
            VALUE_TOL,
        );
        report.check(
            &name,
            "MLL gradient",
            grad_err(g.as_slice(), &m.mll.grad),
            GRAD_TOL,
        );
        let r = fit_gpytorch_mll(&mut gp, FitOptions::default()).unwrap();
        report.check(
            &name,
            "fit: loss above BoTorch's (scaled)",
            (r.loss - m.fit.loss).max(0.0) / FIT_TOL.max(10.0 * m.fit.floor),
            1.0,
        );
        println!(
            "{name:32} fit: loss {:+.10} (BoTorch {:+.10}, floor {:.1e}), iterations {} \
             (BoTorch {}), max parameter difference {:.1e}",
            r.loss,
            m.fit.loss,
            m.fit.floor,
            r.iterations,
            m.fit.iterations,
            gp.raw_parameters()
                .iter()
                .zip(&m.fit.raw_params)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max)
        );
    }
    report.finish("Interval vs GPyTorch");
}

#[test]
fn rows_helper_is_consistent() {
    // `rows` converts a fixture matrix of possibly non-finite numbers.
    let r = rows(&[vec![F(1.0), F(f64::INFINITY)]]);
    assert_eq!(r[0][1], f64::INFINITY);
}
